function containsNearbyDuplicate(nums: number[], k: number): boolean {
  // Значение -> последний индекс, где оно встречалось
  const lastIndex = new Map<number, number>();

  for (let i = 0; i < nums.length; i++) {
    const prev = lastIndex.get(nums[i]);

    // Такое же значение было не дальше k позиций назад
    if (prev !== undefined && i - prev <= k) return true;

    // Обновляем на текущий индекс: он ближе к будущим элементам
    lastIndex.set(nums[i], i);
  }

  return false;
}

// Время: O(n)
// Память: O(n)
